BEGIN;
CREATE SCHEMA control;
CREATE SCHEMA app;
CREATE TABLE control.schema_migration (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control.source (id text PRIMARY KEY, access_class text NOT NULL);
CREATE TABLE control.source_alias (source_id text NOT NULL REFERENCES control.source, scope text NOT NULL, alias text NOT NULL, PRIMARY KEY(scope, alias));
CREATE TABLE control.dataset (id text PRIMARY KEY, source_id text NOT NULL REFERENCES control.source, contract_version text NOT NULL, access_class text NOT NULL);
CREATE TABLE control.partition (id text PRIMARY KEY, dataset_id text NOT NULL REFERENCES control.dataset);
CREATE TABLE control.artifact (id uuid PRIMARY KEY, partition_id text NOT NULL REFERENCES control.partition, object_key text NOT NULL UNIQUE, sha256 text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'), CHECK ((object_key ~ '^raw/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[0-9a-f]{64}$' AND object_key LIKE '%/' || sha256) OR (object_key ~ '^parquet/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[A-Za-z0-9_-]+/[0-9a-f]{64}\.parquet$' AND object_key LIKE '%/' || sha256 || '.parquet')), access_class text NOT NULL, UNIQUE(id, partition_id));
CREATE TABLE control.acquisition (id uuid PRIMARY KEY, artifact_id uuid NOT NULL REFERENCES control.artifact, acquired_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control.run (id uuid PRIMARY KEY, idempotency_key text NOT NULL UNIQUE);
CREATE TABLE control.run_attempt (id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES control.run, started_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control.worker_identity (login name PRIMARY KEY, owner uuid NOT NULL UNIQUE);
CREATE TABLE control.partition_lease (partition_id text PRIMARY KEY REFERENCES control.partition, owner uuid NOT NULL, token bigint NOT NULL CHECK(token > 0), expires_at timestamptz NOT NULL);
CREATE TABLE control.partition_manifest (id uuid PRIMARY KEY, partition_id text NOT NULL REFERENCES control.partition, token bigint NOT NULL, UNIQUE(partition_id, token), UNIQUE(id, partition_id));
CREATE TABLE control.manifest_artifact (manifest_id uuid NOT NULL, partition_id text NOT NULL, artifact_id uuid NOT NULL, PRIMARY KEY(manifest_id, artifact_id), FOREIGN KEY(manifest_id, partition_id) REFERENCES control.partition_manifest(id, partition_id), FOREIGN KEY(artifact_id, partition_id) REFERENCES control.artifact(id, partition_id));
CREATE TABLE control.entity (id uuid PRIMARY KEY);
CREATE TABLE control.identifier (namespace text NOT NULL, scope text NOT NULL, value text NOT NULL, entity_id uuid NOT NULL REFERENCES control.entity, PRIMARY KEY(namespace, scope, value));
CREATE TABLE control.identity_decision (id uuid PRIMARY KEY, entity_id uuid NOT NULL REFERENCES control.entity, version text NOT NULL, evidence jsonb NOT NULL);
CREATE TABLE control.quality_result (id uuid PRIMARY KEY, manifest_id uuid NOT NULL REFERENCES control.partition_manifest, passed boolean NOT NULL, evidence jsonb NOT NULL);
CREATE TABLE control.projection_job (id uuid PRIMARY KEY, manifest_id uuid NOT NULL REFERENCES control.partition_manifest, projection_version text NOT NULL, UNIQUE(manifest_id, projection_version));
CREATE TABLE control.outbox (id uuid PRIMARY KEY, job_id uuid NOT NULL UNIQUE REFERENCES control.projection_job, acknowledged_at timestamptz);
CREATE TABLE control.release_bundle (id uuid PRIMARY KEY, status text NOT NULL CHECK(status IN ('draft','verified')), graph_target text NOT NULL, contract_version text NOT NULL, identity_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control.release_partition (release_id uuid NOT NULL REFERENCES control.release_bundle, partition_id text NOT NULL REFERENCES control.partition, PRIMARY KEY(release_id, partition_id));
CREATE TABLE control.release_manifest (release_id uuid NOT NULL REFERENCES control.release_bundle, manifest_id uuid NOT NULL REFERENCES control.partition_manifest, PRIMARY KEY(release_id, manifest_id));
CREATE TABLE control.active_release (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), release_id uuid NOT NULL REFERENCES control.release_bundle);
CREATE TABLE app.users (id uuid PRIMARY KEY);
CREATE TABLE app.investigations (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app.users);
CREATE TABLE app.annotations (id uuid PRIMARY KEY, investigation_id uuid NOT NULL REFERENCES app.investigations, body text NOT NULL);
INSERT INTO control.schema_migration(version) VALUES (1);
COMMIT;
